/**
 * Cloudflare Workers entry (wrangler.jsonc "main"). Wraps the worker OpenNext generates:
 *  - loads the build facts (src/lib/runtime/build-facts.ts) once per isolate before the first
 *    request, so pages that read the build directory in Node work the same on Workers;
 *  - runs the daily job (retention purges + WhatsApp follow-ups) from the Cron Trigger by calling
 *    POST /api/jobs/follow-up with the CRON_SECRET, through the normal app pipeline.
 */
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { BUILD_FACTS_PATH, setBuildFacts, type BuildFacts } from "./src/lib/runtime/build-facts";

type Env = {
  ASSETS: { fetch(input: Request | string): Promise<Response> };
  CRON_SECRET?: string;
  NEXT_PUBLIC_SITE_URL?: string;
};
type Ctx = { waitUntil(p: Promise<unknown>): void; passThroughOnException?(): void };
type NextHandler = { fetch(req: Request, env: Env, ctx: Ctx): Promise<Response> };

let facts: Promise<void> | null = null;
function loadFacts(env: Env): Promise<void> {
  facts ??= env.ASSETS.fetch(new Request(new URL(BUILD_FACTS_PATH, "https://assets.local")))
    .then(async (r) => {
      if (r.ok) setBuildFacts((await r.json()) as BuildFacts);
      else console.warn(`build facts: ${r.status} (font and 3D preloads off)`);
    })
    .catch((e) => {
      console.warn("build facts:", e);
      facts = null; // retry on the next request
    });
  return facts;
}

const worker = {
  async fetch(request: Request, env: Env, ctx: Ctx): Promise<Response> {
    await loadFacts(env);
    return (handler as NextHandler).fetch(request, env, ctx);
  },

  async scheduled(_event: unknown, env: Env, ctx: Ctx): Promise<void> {
    await loadFacts(env);
    const site = env.NEXT_PUBLIC_SITE_URL || "https://localhost";
    const res = await (handler as NextHandler).fetch(
      new Request(new URL("/api/jobs/follow-up", site), { method: "POST", headers: { authorization: `Bearer ${env.CRON_SECRET ?? ""}` } }),
      env,
      ctx,
    );
    const body = await res.text();
    if (!res.ok) throw new Error(`daily job failed: ${res.status} ${body.slice(0, 500)}`);
    console.log(`daily job: ${body.slice(0, 2000)}`);
  },
};

export default worker;

// OpenNext's Durable Object classes (only needed if the DO queue / tag cache are enabled).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore generated at build time
export { DOQueueHandler, DOShardedTagCache } from "./.open-next/worker.js";
